});
app.MapGet("/orders/{id:int}", (int id, OrderStore store) => store.Find(id));

app.Run();

public class AuthModule : IHttpModule {
    public void Init(HttpApplication app) {
        app.AuthenticateRequest += (s, e) => {
            var ctx = ((HttpApplication)s).Context;
            if (!ctx.User.Identity.IsAuthenticated) ctx.Response.StatusCode = 401;
        };
    }
    public void Dispose() { }
}
